{
  "technical_and_design_decisions": [
    "Use Spring Boot configuration properties to externalize the logging directory, allowing it to be set independently of xd.home (U2).",
    "For Teradata Sqoop integration (U1), bundle the Hortonworks Connector for Teradata as a dependency and automatically apply the --connection-manager argument when a Teradata JDBC URL is detected, bypassing the NPE.",
    "Extract the message-bus and serialization codec into the spring-bus module, updating Spring XD to consume them via Maven dependencies (U3, U5).",
    "Extract input/output type conversion logic into the spring-cloud-dataflow module to support custom domain objects (U4).",
    "Implement the singlenode XD Admin SPI using an in-memory Module Launcher that runs within the same JVM (U6).",
    "Implement the Diego Receptor XD Admin SPI to deploy modules as Diego tasks or Long-Running Processes (LRPs) (U7).",
    "Conduct a research spike for s-c-s module self-registration using Spring Cloud service discovery (e.g., Eureka or Consul) (U8)."
  ],
  "assumptions": [
    "The developer has full access to the Spring XD, spring-bus, and spring-cloud-dataflow source code repositories.",
    "Testing environments for Teradata, CF Lattice/Diego, and local single-node execution are readily available.",
    "The Hortonworks Connector for Teradata is compatible with the version of Sqoop used by Spring XD.",
    "The developer is highly experienced with Spring Framework, Sqoop, and Cloud Foundry Diego.",
    "No new external infrastructure is required beyond what is already available for testing."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Teradata Sqoop Integration",
      "activity_description": "Fix the NPE when connecting Sqoop to Teradata by integrating the Hortonworks Connector and updating the Sqoop job execution logic to use the appropriate connection manager.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize Logging Directory",
      "activity_description": "Add configuration properties to allow the logging directory to be set outside of xd.home, specifically targeting RPM installation paths like /var/logs/spring-xd.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Move message-bus to spring-bus",
      "activity_description": "Refactor and move the message-bus code from the Spring XD repository into the spring-bus repository, updating Maven dependencies in Spring XD.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "Move type conversion to spring-cloud-dataflow",
      "activity_description": "Refactor and move input/output type conversion logic from Spring XD to spring-cloud-dataflow to support custom domain objects.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "Move serialization codec to spring-bus",
      "activity_description": "Refactor and move the serialization codec from the Spring XD repository into the spring-bus repository, updating Maven dependencies.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Singlenode XD Admin SPI Implementation",
      "activity_description": "Develop a single JVM implementation of the XD Admin SPI based on the Module Launcher to run data pipeline use-cases locally.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A7",
      "activity_name": "Diego Receptor XD Admin SPI Implementation",
      "activity_description": "Develop a Diego-based Receptor implementation of the XD Admin SPI based on the ModuleLauncher to run data pipeline use-cases on CF Lattice/Diego.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Investigate s-c-s Self-Registration",
      "activity_description": "Investigate and spike the possibility of s-c-s modules self-registering to a service discovery mechanism so Spring XD runtime can discover and orchestrate them.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration Testing",
      "activity_description": "Perform end-to-end testing of all implemented features, including Teradata imports, external logging, moved modules, and Admin SPI implementations.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation",
      "activity_description": "Update project documentation to reflect the new configuration options, moved modules, and Admin SPI implementations.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 186
  }
}
